from typing import Any


class EnvCfgError(Exception):
    """Raised when an environment variable is invalid or unknown."""
    pass


def _coerce(value: str, expected_type: type) -> Any:
    """Coerce a string to the expected type, raising EnvCfgError on failure."""
    if expected_type is int:
        try:
            return int(value)
        except ValueError:
            raise EnvCfgError(f"key expected int, got {value!r}")
    if expected_type is float:
        try:
            return float(value)
        except ValueError:
            raise EnvCfgError(f"key expected float, got {value!r}")
    if expected_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise EnvCfgError(f"key expected bool, got {value!r}")
    if expected_type is str:
        return value
    raise EnvCfgError(f"key expected {expected_type.__name__}, got {value!r}")


